1	<!doctype html>
2	<html lang="ru">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>автопаша — ИИ-сотрудник, которого можно нанять</title>
7	<meta name="description" content="Паша сидит в вашем рабочем чате, сам берёт задачи, делает и приходит с готовым. Неделя 25 000 ₽, в первые 3 дня вернём деньги.">
8	<style>
9	@font-face{font-family:"Unbounded";font-weight:400;font-display:swap;src:url("fonts/Unbounded-400-cyrillic.woff2") format("woff2");unicode-range:U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116}
10	@font-face{font-family:"Unbounded";font-weight:400;font-display:swap;src:url("fonts/Unbounded-400-latin.woff2") format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212}
11	@font-face{font-family:"Unbounded";font-weight:700;font-display:swap;src:url("fonts/Unbounded-700-cyrillic.woff2") format("woff2");unicode-range:U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116}
12	@font-face{font-family:"Unbounded";font-weight:700;font-display:swap;src:url("fonts/Unbounded-700-latin.woff2") format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212}
