14	@font-face{font-family:"Onest";font-weight:300;font-display:swap;src:url("fonts/Onest-300-latin.woff2") format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+2000-206F,U+20AC,U+2122}
15	@font-face{font-family:"Onest";font-weight:400;font-display:swap;src:url("fonts/Onest-400-cyrillic.woff2") format("woff2");unicode-range:U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116}
16	@font-face{font-family:"Onest";font-weight:400;font-display:swap;src:url("fonts/Onest-400-latin.woff2") format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+2000-206F,U+20AC,U+2122}
17	@font-face{font-family:"Onest";font-weight:500;font-display:swap;src:url("fonts/Onest-500-cyrillic.woff2") format("woff2");unicode-range:U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116}
18	@font-face{font-family:"Onest";font-weight:500;font-display:swap;src:url("fonts/Onest-500-latin.woff2") format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+2000-206F,U+20AC,U+2122}
19	@font-face{font-family:"Onest";font-weight:700;font-display:swap;src:url("fonts/Onest-700-cyrillic.woff2") format("woff2");unicode-range:U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116}
20	@font-face{font-family:"Onest";font-weight:700;font-display:swap;src:url("fonts/Onest-700-latin.woff2") format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+2000-206F,U+20AC,U+2122}
21	@font-face{font-family:"JetBrains Mono";font-weight:400;font-display:swap;src:url("fonts/JetBrainsMono-normal-400-cyrillic.woff2") format("woff2");unicode-range:U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116}
22	@font-face{font-family:"JetBrains Mono";font-weight:400;font-display:swap;src:url("fonts/JetBrainsMono-normal-400-latin.woff2") format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+2000-206F,U+20AC,U+2122}
23	@font-face{font-family:"JetBrains Mono";font-weight:600;font-display:swap;src:url("fonts/JetBrainsMono-normal-600-cyrillic.woff2") format("woff2");unicode-range:U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116}
24	@font-face{font-family:"JetBrains Mono";font-weight:600;font-display:swap;src:url("fonts/JetBrainsMono-normal-600-latin.woff2") format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+2000-206F,U+20AC,U+2122}
25	
26	:root{
27	  --bg:#141110; --s1:#1f1a17; --s2:#2a2420; --line:#3a322c;
28	  --ink:#efe8df; --mut:#b5aca3; --or:#fe6e16; --or-txt:#c2410c;
29	  --light:#efe8df; --light-ink:#1d1916;
30	  --ok:#8fbf7a; --wait:#fe6e16; --work:#d9b26a;
31	  --head:"Unbounded",system-ui,sans-serif;
32	  --body:"Onest",system-ui,sans-serif;
33	  --mono:"JetBrains Mono",ui-monospace,monospace;
34	}
35	*{box-sizing:border-box;margin:0;padding:0}
36	html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
37	body{background:var(--bg);color:var(--ink);font-family:var(--body);font-size:17px;line-height:1.5;overflow-x:hidden}
38	img,svg{display:block;max-width:100%}
39	a{color:inherit}
40	button,input{font:inherit;color:inherit}
41	.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
42	.sec{padding:120px 0;border-top:1px solid var(--line)}
43	.eyebrow{font-family:var(--mono);font-size:13px;color:var(--mut);letter-spacing:.02em;display:flex;gap:10px;align-items:center}
44	.eyebrow b{color:var(--or);font-weight:600}
45	h1,h2,h3{font-family:var(--head);font-weight:700;letter-spacing:-.02em;line-height:1.08}
46	h2{font-size:clamp(34px,4vw,52px);margin:18px 0 20px;max-width:18ch}
47	h2 em,h1 em{font-style:normal;color:var(--or)}
48	.lead{color:var(--mut);max-width:58ch;font-size:18px}
49	.mono{font-family:var(--mono)}
50	.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:0 26px;border-radius:10px;background:var(--or);color:#1d1916;font-weight:600;font-size:16px;text-decoration:none;border:0;cursor:pointer;transition:transform .15s,background .15s}
51	.btn:hover{background:#ff8238;transform:translateY(-1px)}
52	.btn:focus-visible,.tab:focus-visible,summary:focus-visible,input:focus-visible{outline:2px solid var(--or);outline-offset:3px}
53	.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}
54	.btn.ghost:hover{background:var(--s1)}
55	.card{background:var(--s1);border:1px solid var(--line);border-radius:14px}
56	.tag{font-family:var(--mono);font-size:12px;color:var(--mut);background:var(--s2);border-radius:6px;padding:3px 8px;white-space:nowrap}
57	.dot{width:8px;height:8px;border-radius:50%;background:var(--mut);display:inline-block;flex:none}
58	.dot.ok{background:var(--ok)} .dot.wait{background:var(--wait)} .dot.work{background:var(--work);animation:pulse 1.6s infinite}
59	@keyframes pulse{50%{opacity:.35}}
60	
61	/* header */
62	header{position:sticky;top:0;z-index:20;background:var(--bg);border-bottom:1px solid var(--line)}
63	header .wrap{display:flex;align-items:center;justify-content:space-between;height:68px;gap:20px}
64	.logo{font-family:var(--head);font-weight:800;font-size:20px;text-decoration:none;display:flex;align-items:center;gap:2px}
65	.plate{background:var(--or);color:#1d1916;border-radius:6px;padding:1px 7px;margin-left:4px}
66	nav.top{display:flex;gap:26px;font-size:15px;color:var(--mut)}
67	nav.top a{text-decoration:none}
68	nav.top a:hover{color:var(--ink)}
69	header .btn{min-height:40px;padding:0 18px;font-size:15px}
70	
71	/* hero */
72	.hero{padding:72px 0 96px}
73	.hero-grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:56px;align-items:start}
74	.hero h1{font-size:clamp(40px,4.6vw,68px);margin:22px 0 48px;max-width:none}
75	.hero .lead{max-width:44ch}
76	.price{margin:32px 0 0;display:flex;flex-wrap:wrap;gap:6px 14px;align-items:baseline}
77	.price .now{font-family:var(--head);font-weight:700;font-size:34px}
78	.price .old{color:var(--mut);text-decoration:line-through;font-size:20px}
79	.price small{width:100%;color:var(--mut);font-size:15px}
80	.hero .cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}
81	.askbox{margin-top:44px;display:grid;gap:10px}
82	.askbox label{font-family:var(--mono);font-size:13px;color:var(--mut)}
83	.askrow{display:flex;gap:8px;background:var(--s1);border:1px solid var(--line);border-radius:12px;padding:6px}
84	.askrow input{flex:1;min-width:0;background:transparent;border:0;padding:0 12px;min-height:44px;font-size:16px}
85	.askrow input::placeholder{color:#7d746c}
86	.askrow .btn{min-height:44px;padding:0 18px;font-size:15px}
87	
88	.stage{display:grid;gap:14px}
89	.chat{background:var(--s1);border:1px solid var(--line);border-radius:16px;overflow:hidden}
90	.chat-h{display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid var(--line);background:var(--s2)}
91	.chat-h img{width:36px;height:36px;border-radius:10px;background:var(--s1)}
92	.chat-h .who{font-weight:600;font-size:15px}
93	.chat-h .who span{display:block;font-family:var(--mono);font-size:12px;color:var(--ok);font-weight:400}
94	.chat-b{padding:18px;display:flex;flex-direction:column;gap:12px;min-height:380px}
95	.msg{max-width:84%;padding:10px 14px;border-radius:12px;font-size:15px;line-height:1.45;background:var(--s2);animation:in .45s ease both}
96	.msg.me{align-self:flex-end;background:#3a2c20;border:1px solid #5a3f2a}
97	.msg .t{display:block;font-family:var(--mono);font-size:11px;color:var(--mut);margin-top:4px}
98	.msg.voice{display:grid;gap:8px;min-width:260px}
99	.voice-bar{display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:13px}
100	.voice-bar i{flex:1;height:4px;background:var(--line);border-radius:2px;position:relative;overflow:hidden}
101	.voice-bar i::after{content:"";position:absolute;inset:0;width:40%;background:var(--or)}
102	.voice-tx{font-size:14px;color:var(--mut);border-top:1px dashed var(--line);padding-top:8px}
103	.typing{align-self:flex-start;font-family:var(--mono);font-size:13px;color:var(--mut);padding:4px 2px;animation:in .3s ease both}
104	@keyframes in{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
105	
106	.tasks{display:grid;gap:10px}
107	.tcard{background:var(--s1);border:1px solid var(--line);border-radius:12px;padding:14px 16px;cursor:default;transition:border-color .2s}
108	.tcard:hover,.tcard.open{border-color:#5a4a3c}
109	.trow{display:flex;align-items:center;gap:12px;justify-content:space-between}
110	.trow .name{font-size:15px;font-weight:500;display:flex;gap:10px;align-items:center;min-width:0}
111	.trow .name span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
112	.tmeta{display:flex;justify-content:space-between;font-family:var(--mono);font-size:12px;color:var(--mut);margin-top:6px}
113	.steps{display:none;margin-top:10px;padding-top:10px;border-top:1px dashed var(--line);font-family:var(--mono);font-size:13px;color:var(--mut);line-height:1.7}
114	.tcard:hover .steps,.tcard.open .steps{display:block}
115	.steps div::before{content:"› ";color:var(--or)}
116	.stat{font-family:var(--mono);font-size:12px;color:var(--mut)}
117	.stat b{color:var(--ink);font-weight:600}
118	.counter{display:flex;justify-content:space-between;align-items:center;font-family:var(--mono);font-size:13px;color:var(--mut);padding:0 2px}
119	.counter b{font-family:var(--head);font-size:22px;color:var(--ink);font-weight:700}
120	
121	/* sections */
122	.works-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:56px}
123	.job{padding:24px;display:flex;flex-direction:column;gap:14px;min-height:260px}
124	.job .cat{font-family:var(--mono);font-size:12px;color:var(--or);text-transform:uppercase;letter-spacing:.06em}
125	.job q{font-size:18px;line-height:1.4;font-weight:500;quotes:"«" "»"}
126	.job .did{font-size:15px;color:var(--mut)}
127	.job .did b{color:var(--ink);font-weight:500}
128	.job .sys{margin-top:auto;display:flex;gap:6px;flex-wrap:wrap;align-items:center}
129	
130	.where{display:grid;grid-template-columns:minmax(0,4fr) minmax(0,8fr);gap:40px;align-items:center;margin-top:56px}
131	.where-note{display:grid;gap:14px}
132	.where-note p{color:var(--mut)}
133	.platforms{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}
134	.screen{position:relative;background:var(--s1);border:1px solid var(--line);border-radius:18px;padding:16px;min-width:0}
135	.tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px}
136	.tab{background:transparent;border:1px solid var(--line);color:var(--mut);border-radius:8px;padding:8px 12px;font-size:14px;cursor:pointer;transition:all .2s}
137	.tab[aria-selected="true"]{background:var(--or);border-color:var(--or);color:#1d1916;font-weight:600}
138	.panel{min-height:330px;background:var(--bg);border-radius:12px;padding:18px;display:none;flex-direction:column;gap:10px}
139	.panel.on{display:flex;animation:in .4s ease both}
140	.panel .msg{max-width:90%}
141	.panel .msg.bot{background:var(--s2)}
142	.ask-buttons{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}
143	.ask-buttons span{font-size:14px;border-radius:8px;padding:8px 12px;border:1px solid var(--line);color:var(--ink)}
144	.ask-buttons span:first-child{background:var(--or);border-color:var(--or);color:#1d1916;font-weight:600}
145	.board{display:grid;gap:8px}
146	.board div{background:var(--s1);border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:14px;display:flex;justify-content:space-between;gap:10px;align-items:center}
147	.board small{font-family:var(--mono);color:var(--mut);font-size:12px;white-space:nowrap}
148	.outside{position:absolute;inset:auto;pointer-events:none}
149	.where-ring{position:relative;padding:20px 0}
150	.where-ring .tag{position:absolute}
151	.where-ring .r1{top:-6px;left:4%} .where-ring .r2{top:-6px;right:4%} .where-ring .r3{bottom:-6px;left:0} .where-ring .r4{bottom:-6px;right:0}
152	
153	/* comparison */
154	.light{background:var(--light);color:var(--light-ink);border-top:0}
155	.light .lead,.light .muted{color:#5b5149}
156	.light .eyebrow,.light .eyebrow b{color:#5b5149} .light .eyebrow b{color:var(--or-txt)}
157	.cmp{margin-top:48px;background:#fbf8f3;border:1px solid #d9cfc3;border-radius:16px;overflow:hidden}
158	.cmp-row{display:grid;grid-template-columns:minmax(120px,1.1fr) repeat(3,minmax(0,1fr));border-top:1px solid #e3dad0;align-items:center}
159	.cmp-row:first-child{border-top:0;background:#f3ede4}
160	.cmp-row>*{padding:16px 18px;font-size:15px;min-width:0}
161	.cmp-row .k{font-weight:500}
162	.cmp-row.head>*{font-family:var(--mono);font-size:12px;color:#5b5149;text-transform:uppercase;letter-spacing:.04em}
163	.cmp-row .pasha{background:var(--or);color:#1d1916;font-weight:600;align-self:stretch;display:flex;align-items:center}
164	.cmp-row.head .pasha{color:#1d1916;background:var(--or)}
165	.bar{height:6px;border-radius:3px;background:#e3dad0;margin-top:8px;overflow:hidden}
166	.bar i{display:block;height:100%;width:0;background:#8a7f75;transition:width 1.2s cubic-bezier(.2,.7,.2,1)}
167	.bar.p i{background:#1d1916}
168	.cmp-foot{margin-top:18px;color:#5b5149;font-size:15px}
169	
170	/* permissions */
171	.perm-wrap{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:48px;align-items:center;margin-top:56px}
172	.who-card{display:flex;align-items:center;gap:16px;background:var(--s1);border:1px solid var(--line);border-radius:16px;padding:18px}
173	.who-card img{width:64px;height:64px;border-radius:16px;background:var(--s2);padding:6px}
174	.who-card b{font-family:var(--head);font-size:20px}
175	.who-card span{display:block;color:var(--mut);font-size:14px}
176	.menu{margin-top:16px;background:var(--s2);border:1px solid var(--line);border-radius:14px;overflow:hidden}
177	.menu-i{padding:16px 18px;border-bottom:1px solid var(--line);display:grid;gap:4px}
178	.menu-i:last-child{border-bottom:0}
179	.menu-i b{font-weight:500;font-size:16px}
180	.menu-i small{color:var(--mut);font-size:14px}
181	.menu-i .mode{font-family:var(--mono);font-size:12px;color:var(--or);margin-top:2px}
182	.menu-i.no{opacity:.55}
183	.menu-i.no b{text-decoration:line-through}
184	.menu-i.no .mode{color:var(--mut)}
185	.perm-list{display:grid;gap:10px}
186	.perm-list div{display:flex;gap:14px;align-items:flex-start;padding:4px 0}
187	.perm-list .n{font-family:var(--mono);color:var(--or);font-size:14px;padding-top:2px}
188	.perm-list p{color:var(--mut)}
189	.perm-list p b{color:var(--ink);font-weight:500}
190	
191	/* activity */
192	.act-wrap{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:24px;margin-top:56px;align-items:start}
193	.feed{background:var(--s1);border:1px solid var(--line);border-radius:16px;overflow:hidden}
194	.feed-h{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid var(--line);font-family:var(--mono);font-size:13px;color:var(--mut)}
195	.feed-list{list-style:none;max-height:440px;overflow:hidden;position:relative}
196	.feed-list li{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;padding:13px 18px;border-bottom:1px solid var(--line);font-size:15px;animation:slide .5s ease both}
197	.feed-list li:last-child{border-bottom:0}
198	.feed-list .what{min-width:0}
199	.feed-list .what span{display:block;font-family:var(--mono);font-size:12px;color:var(--mut)}
200	.feed-list .when{font-family:var(--mono);font-size:12px;color:var(--mut);white-space:nowrap}
201	.st{font-family:var(--mono);font-size:12px;padding:3px 8px;border-radius:6px;white-space:nowrap}
202	.st.done{background:#25321f;color:#b9e0a5}
203	.st.wait{background:#3d2715;color:#ffb27a}
204	.st.work{background:#3a3016;color:#f1d28e}
205	@keyframes slide{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:none}}
206	.side{display:grid;gap:16px}
207	.file{padding:22px}
208	.file h3{font-size:20px;margin-bottom:12px}
209	.file dl{display:grid;gap:12px}
210	.file dt{font-family:var(--mono);font-size:12px;color:var(--mut);text-transform:uppercase;letter-spacing:.04em}
211	.file dd{font-size:15px;margin-top:2px}
212	.file .big{font-family:var(--head);font-weight:700;font-size:40px;letter-spacing:-.02em}
213	
214	/* pricing */
215	.price-wrap{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:56px}
216	.plan{padding:32px;display:flex;flex-direction:column;gap:14px}
217	.plan .lbl{font-family:var(--mono);font-size:13px;color:var(--mut);text-transform:uppercase;letter-spacing:.06em}
218	.plan .amt{font-family:var(--head);font-weight:700;font-size:clamp(36px,4vw,52px);letter-spacing:-.02em;display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}
219	.plan .amt s{font-size:20px;color:var(--mut);font-weight:400;font-family:var(--body)}
220	.plan.hot{border-color:var(--or)}
221	.plan.hot .amt{color:var(--ink)}
222	.plan .note{color:var(--mut);font-size:15px}
223	.plan .btn{margin-top:auto}
224	.disc{margin-top:16px;padding:20px 24px;display:flex;gap:18px;align-items:center;flex-wrap:wrap;justify-content:space-between}
225	.disc b{font-family:var(--head);font-size:20px}
226	.disc span{color:var(--mut);font-size:15px}
227	.incl{margin-top:16px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;border-top:1px solid var(--line)}
228	.incl li{list-style:none;padding:16px 0;border-bottom:1px solid var(--line);display:flex;gap:12px;font-size:16px}
229	.incl li::before{content:"✓";color:var(--or);font-family:var(--mono)}
