694	  ];
695	
696	  var chat = document.getElementById('chat');
697	  var presence = document.getElementById('presence');
698	
699	  function node(m){
700	    var d = document.createElement('div');
701	    if (m.who === 'typing') { d.className = 'typing'; d.textContent = 'Паша печатает…'; return d; }
702	    if (m.voice) {
