705	      return d;
706	    }
707	    d.className = 'msg' + (m.who === 'me' ? ' me' : '');
708	    d.textContent = m.text;
709	    if (m.t) { var s = document.createElement('span'); s.className = 't'; s.textContent = m.t; d.appendChild(s); }
710	    return d;
711	  }
712	
713	  if (reduce) {
714	    script.forEach(function(m){ if (m.who !== 'typing') chat.appendChild(node(m)); });
715	  } else {
716	    var i = 0;
717	    (function next(){
718	      if (i >= script.length) { presence.textContent = 'в сети'; return; }
719	      var m = script[i++];
720	      if (m.who === 'typing') {
721	        var t = node(m); chat.appendChild(t); presence.textContent = 'печатает…';
722	        setTimeout(function(){ t.remove(); presence.textContent = 'в сети'; next(); }, 1600);
723	        return;
724	      }
725	      chat.appendChild(node(m));
726	      setTimeout(next, m.voice ? 2400 : 1100);
727	    })();
728	  }
729	
730	  var statusCycle = [
731	    [['в работе','work'],['ждёт вашей кнопки','wait'],['готово','ok']],
732	    [['ждёт вашей кнопки','wait'],['в работе','work'],['готово','ok']],
733	    [['готово','ok'],['в работе','work'],['готово','ok']]
734	  ];
735	  var cards = document.querySelectorAll('#tasks .tcard');
736	  var phase = 0;
737	  var dotMap = {work:'dot work', wait:'dot wait', ok:'dot ok'};
738	  function applyStatus(){
739	    cards.forEach(function(c, idx){
740	      var s = statusCycle[idx][phase % statusCycle[idx].length];
741	      c.querySelector('[data-st]').textContent = s[0];
742	      c.querySelector('[data-dot]').className = dotMap[s[1]] + '';
743	    });
744	    phase++;
745	  }
746	  if (!reduce) setInterval(applyStatus, 4200);
747	
748	  cards.forEach(function(c){
749	    c.addEventListener('click', function(){ c.classList.toggle('open'); });
750	  });
751	
752	  var tabs = document.querySelectorAll('.tab');
753	  tabs.forEach(function(tb){
