759	        var on = p.getAttribute('data-p') === key;
760	        p.classList.toggle('on', on);
761	      });
762	    });
763	  });
764	
765	  var counter = document.getElementById('done-count');
766	  var feedDone = document.querySelectorAll('.st.done').length + 12;
767	  function countUp(el, to){
768	    if (reduce) { el.textContent = to; return; }
769	    var n = 0, step = Math.max(1, Math.ceil(to / 30));
770	    var iv = setInterval(function(){ n = Math.min(to, n + step); el.textContent = n; if (n >= to) clearInterval(iv); }, 40);
771	  }
772	
773	  var feed = document.getElementById('feed');
