778	  ];
779	  var ei = 0;
780	
781	  var io = 'IntersectionObserver' in window ? new IntersectionObserver(function(entries){
782	    entries.forEach(function(e){
783	      if (!e.isIntersecting) return;
784	      e.target.classList.add('in');
785	      if (e.target.id === 'cmp') e.target.querySelectorAll('.bar i').forEach(function(b){ b.style.width = b.parentNode.getAttribute('data-w') + '%'; });
786	      if (e.target.id === 'feed') countUp(counter, feedDone);
