import sys, json
from playwright.sync_api import sync_playwright
base = "file:///opt/autopasha/work/design-ideas/maket-b/index.html"
with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h, name in [(1440, 900, "1440"), (390, 844, "390")]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(base, wait_until="load")
        pg.wait_for_timeout(300)
        total = pg.evaluate("document.documentElement.scrollHeight")
        y = 0
        while y < total:
            pg.evaluate(f"window.scrollTo(0,{y})"); pg.wait_for_timeout(120); y += 400
        pg.evaluate("window.scrollTo(0,0)"); pg.wait_for_timeout(1500)
        info = pg.evaluate("""() => {
          const out = {scrollW: document.documentElement.scrollWidth, clientW: document.documentElement.clientWidth, sections: []};
          document.querySelectorAll('section, .final').forEach(s => {
            const r = s.getBoundingClientRect();
            out.sections.push([s.id || s.className, Math.round(r.height)]);
          });
          const over = [];
          document.querySelectorAll('body *').forEach(el => {
            const r = el.getBoundingClientRect();
            if (r.width && (r.right > document.documentElement.clientWidth + 1 || r.left < -1)) over.push(el.className || el.tagName);
          });
          out.overflow = over.slice(0, 10);
          out.counter = document.getElementById('done-count').textContent;
          return out;
        }""")
        print(name, json.dumps(info, ensure_ascii=False))
        pg.screenshot(path=f"shots/{name}.png", full_page=True)
        pg.close()
    b.close()
EOF
